pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0));
        uint256 before = c.proposalCount();
        c.newGrantProposal(recipient, amount);
        uint256 afterC = c.proposalCount();
        assertTrue(afterC == before + 1 && c.mapPID_grant(afterC).recipient == recipient,
            "each grant proposal increments proposalCount by exactly 1 and registers at the new id");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0));
        c.newGrantProposal(recipient, amount);
        c.newGrantProposal(recipient, amount);
        // General rule: each grant proposal occupies one consecutive ID, so the
        // first ID (1) must carry the "GRANT" type after any grant proposals.
        assertTrue(bytes(c.mapPID_type(1)).length > 0,
            "proposal ID 1 must have a type (consecutive IDs)");
    }
}

